from collections import deque, Counter

def _components(grid, colors, min_col):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(min_col, w):
            color = grid[r][c]
            if color not in colors or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and min_col <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            result.append((color, cells))
    return result

def _norm(cells):
    r0 = min(r for r,c in cells); c0 = min(c for r,c in cells)
    return frozenset((r-r0,c-c0) for r,c in cells)

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row if v)
    frame = counts.most_common(1)[0][0]
    # The framed panels occupy the contiguous leading columns that contain frame color.
    left_w = 0
    for c in range(w):
        if any(g[r][c] == frame for r in range(h)):
            left_w = c + 1
        elif left_w:
            break
    # Entirely framed rows divide the pattern into panels.
    separators = [r for r in range(h) if all(g[r][c] == frame for c in range(left_w))]
    sep_set = set(separators)
    objs = _components(g, set(counts) - {frame}, left_w)
    obj_by_shape = {}
    for color, cells in objs:
        obj_by_shape[_norm(cells)] = color
    start = 0
    for end in separators + [h]:
        rows = [r for r in range(start, end) if r not in sep_set]
        if rows:
            holes = [(r,c) for r in rows for c in range(1, left_w-1) if g[r][c] == 0]
            if holes:
                key = _norm(holes)
                color = obj_by_shape.get(key)
                if color is not None:
                    for r,c in holes:
                        g[r][c] = color
        start = end + 1
    return [row[:left_w] for row in g]
